    //go:nosplit
    sudog* acquireSudog()
    {
        // Delicate dance: the semaphore implementation calls
        // acquireSudog, acquireSudog calls new(sudog),
        // new calls malloc, malloc can call the garbage collector,
        // and the garbage collector calls the semaphore implementation
        // in stopTheWorld.
        // Break the cycle by doing acquirem/releasem around new(sudog).
        // The acquirem/releasem increments m.locks during new(sudog),
        // which keeps the garbage collector from being invoked.
        auto mp = acquirem();
        auto pp = rec::ptr(gocpp::recv(mp->p));
        if(len(pp->sudogcache) == 0)
        {
            lock(& sched.sudoglock);
            // First, try to grab a batch from central cache.
            for(; len(pp->sudogcache) < cap(pp->sudogcache) / 2 && sched.sudogcache != nullptr; )
            {
                auto s = sched.sudogcache;
                sched.sudogcache = s->next;
                s->next = nullptr;
                pp->sudogcache = append(pp->sudogcache, s);
            }
            unlock(& sched.sudoglock);
            // If the central cache is empty, allocate a new one.
            if(len(pp->sudogcache) == 0)
            {
                pp->sudogcache = append(pp->sudogcache, new sudog{});
            }
        }
        auto n = len(pp->sudogcache);
        auto s = pp->sudogcache[n - 1];
        pp->sudogcache[n - 1] = nullptr;
        pp->sudogcache = pp->sudogcache.make_slice(0, n - 1);
        if(rec::get(gocpp::recv(s->elem)) != nullptr)
        {
            go_throw("acquireSudog: found s.elem != nil in cache"_s);
        }
        releasem(mp);
        return s;
    }

    //go:nosplit
    void releaseSudog(sudog* s)
    {
        if(rec::get(gocpp::recv(s->elem)) != nullptr)
        {
            go_throw("runtime: sudog with non-nil elem"_s);
        }
        if(s->isSelect)
        {
            go_throw("runtime: sudog with non-false isSelect"_s);
        }
        if(s->next != nullptr)
        {
            go_throw("runtime: sudog with non-nil next"_s);
        }
        if(s->prev != nullptr)
        {
            go_throw("runtime: sudog with non-nil prev"_s);
        }
        if(s->waitlink != nullptr)
        {
            go_throw("runtime: sudog with non-nil waitlink"_s);
        }
        if(rec::get(gocpp::recv(s->c)) != nullptr)
        {
            go_throw("runtime: sudog with non-nil c"_s);
        }
        auto gp = getg();
        if(gp->param != nullptr)
        {
            go_throw("runtime: releaseSudog with non-nil gp.param"_s);
        }
        // avoid rescheduling to another P
        auto mp = acquirem();
        auto pp = rec::ptr(gocpp::recv(mp->p));
        if(len(pp->sudogcache) == cap(pp->sudogcache))
        {
            // Transfer half of local cache to the central cache.
            sudog* first = {};
            sudog* last = {};
            for(; len(pp->sudogcache) > cap(pp->sudogcache) / 2; )
            {
                auto n = len(pp->sudogcache);
                auto p = pp->sudogcache[n - 1];
                pp->sudogcache[n - 1] = nullptr;
                pp->sudogcache = pp->sudogcache.make_slice(0, n - 1);
                if(first == nullptr)
                {
                    first = p;
                }
                else
                {
                    last->next = p;
                }
                last = p;
            }
            lock(& sched.sudoglock);
            last->next = sched.sudogcache;
            sched.sudogcache = first;
            unlock(& sched.sudoglock);
        }
        pp->sudogcache = append(pp->sudogcache, s);
        releasem(mp);
    }

